import{_ as s,a,c as o,ac as r}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第8–15课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第8–15课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第1–7课","link":"/life/english/new-concept/book-1/review-part-01"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第16–23课","link":"/life/english/new-concept/book-1/review-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第1–7课","link":"/life/english/new-concept/book-1/review-part-01"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第16–23课","link":"/life/english/new-concept/book-1/review-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-02.md","filePath":"life/english/new-concept/book-1/review-part-02.md"}'),t={name:"life/english/new-concept/book-1/review-part-02.md"};function n(i,e,l,h,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第8–15课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第8–15课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第8–15课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第8–15课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-8-·-a-an-与职业名词" tabindex="-1">Lesson 8 · a/an 与职业名词 <a class="header-anchor" href="#lesson-8-·-a-an-与职业名词" aria-label="Permalink to &quot;Lesson 8 · a/an 与职业名词 {#lesson-8-·-a-an-与职业名词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Are your parents teachers?</p><h3 id="练习-1-7" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-7" aria-label="Permalink to &quot;练习 1 {#练习-1-7}&quot;">​</a></h3><p>填 be：Your parents ___ teachers.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> are</p><p><strong>解析：</strong> 按本课规则判断：单数可数职业名词作表语时一般加 a 或 an。选择取决于紧接着的读音，不是字母名称；engineer 前用 an，teacher 前用 a。What is your job? 询问职业，回答可用 I am a/an ...。be 必须与主语一致：I am、you are、he/she is；不能用职业名词直接作谓语。</p></details><p><strong>表达迁移：</strong> 围绕“询问职业并给出完整身份信息”写两至三句，再读给同伴听。至少使用一次a/an 与职业名词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Are your parents teachers? My sister is an engineer.</p><p>Your parents 是复数主语，问句将 are 提前；teachers 为复数职业，不加 a/an。 My sister 为第三人称单数主语，后接 is；engineer 的首音是元音音素，因此用 an，而非 a。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-008">回看本课</a></p><h2 id="lesson-9-·-be-形容词" tabindex="-1">Lesson 9 · be + 形容词 <a class="header-anchor" href="#lesson-9-·-be-形容词" aria-label="Permalink to &quot;Lesson 9 · be + 形容词 {#lesson-9-·-be-形容词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Our new neighbour is very friendly.</p><h3 id="练习-1-8" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-8" aria-label="Permalink to &quot;练习 1 {#练习-1-8}&quot;">​</a></h3><p>补全：Our new neighbour ___ very friendly.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 按本课规则判断：形容词表示状态或性质，常放在 be 后作表语。英语一般不能像中文一样直接说“我很好”而省略 be。How are you? 询问近况，不等于询问身份；其回答可用 I am well/fine。look at 中 at 后接观察对象。形容词通常不因名词单复数增加 s。</p></details><p><strong>表达迁移：</strong> 围绕“问候身体状态并描述外观”写两至三句，再读给同伴听。至少使用一次be + 形容词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Our new neighbour is very friendly. Look at the young artist.</p><p>Our new neighbour 是单数主语，is 连接表语 friendly；very 修饰形容词 friendly，说明友好程度。 Look 是祈使句谓语，省略主语 you；at 引出观察对象 the young artist，young 在名词前作定语。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-009">回看本课</a></p><h2 id="lesson-10-·-be-形容词" tabindex="-1">Lesson 10 · be + 形容词 <a class="header-anchor" href="#lesson-10-·-be-形容词" aria-label="Permalink to &quot;Lesson 10 · be + 形容词 {#lesson-10-·-be-形容词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Look at the young artist.</p><h3 id="练习-1-9" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-9" aria-label="Permalink to &quot;练习 1 {#练习-1-9}&quot;">​</a></h3><p>补介词：Look ___ the artist.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> at</p><p><strong>解析：</strong> 按本课规则判断：形容词表示状态或性质，常放在 be 后作表语。英语一般不能像中文一样直接说“我很好”而省略 be。How are you? 询问近况，不等于询问身份；其回答可用 I am well/fine。look at 中 at 后接观察对象。形容词通常不因名词单复数增加 s。</p></details><p><strong>表达迁移：</strong> 围绕“问候身体状态并描述外观”写两至三句，再读给同伴听。至少使用一次be + 形容词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Look at the young artist. Our new neighbour is very friendly.</p><p>Look 是祈使句谓语，省略主语 you；at 引出观察对象 the young artist，young 在名词前作定语。 Our new neighbour 是单数主语，is 连接表语 friendly；very 修饰形容词 friendly，说明友好程度。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-010">回看本课</a></p><h2 id="lesson-11-·-whose-与物主限定词" tabindex="-1">Lesson 11 · whose 与物主限定词 <a class="header-anchor" href="#lesson-11-·-whose-与物主限定词" aria-label="Permalink to &quot;Lesson 11 · whose 与物主限定词 {#lesson-11-·-whose-与物主限定词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Whose scarf is that?</p><h3 id="练习-1-10" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-10" aria-label="Permalink to &quot;练习 1 {#练习-1-10}&quot;">​</a></h3><p>选择 whose/who&#39;s：___ scarf is that?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Whose</p><p><strong>解析：</strong> 按本课规则判断：whose 询问“谁的”，可接名词构成 Whose shirt is this?。回答用 my/your/his/her + 名词；his 可直接放在名词前，her 表示女性所属。whose 与 who&#39;s 不同，后者是 who is 或 who has 的缩写。谈到具体物品时要保持 this/that 与单数、these/those 与复数一致。</p></details><p><strong>表达迁移：</strong> 围绕“区分询问归属与询问人物”写两至三句，再读给同伴听。至少使用一次whose 与物主限定词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Whose scarf is that? This is his bicycle.</p><p>Whose scarf 是疑问词组，询问归属；is 前置，that 是主语。whose 后接 scarf，不能换成 who&#39;s。 This 是主语，is 是系动词，his bicycle 是表语；his 在 bicycle 前用作物主限定词。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-011">回看本课</a></p><h2 id="lesson-12-·-whose-与物主限定词" tabindex="-1">Lesson 12 · whose 与物主限定词 <a class="header-anchor" href="#lesson-12-·-whose-与物主限定词" aria-label="Permalink to &quot;Lesson 12 · whose 与物主限定词 {#lesson-12-·-whose-与物主限定词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> This is his bicycle.</p><h3 id="练习-1-11" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-11" aria-label="Permalink to &quot;练习 1 {#练习-1-11}&quot;">​</a></h3><p>填“他的”：This is ___ bicycle.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> his</p><p><strong>解析：</strong> 按本课规则判断：whose 询问“谁的”，可接名词构成 Whose shirt is this?。回答用 my/your/his/her + 名词；his 可直接放在名词前，her 表示女性所属。whose 与 who&#39;s 不同，后者是 who is 或 who has 的缩写。谈到具体物品时要保持 this/that 与单数、these/those 与复数一致。</p></details><p><strong>表达迁移：</strong> 围绕“区分询问归属与询问人物”写两至三句，再读给同伴听。至少使用一次whose 与物主限定词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This is his bicycle. Whose scarf is that?</p><p>This 是主语，is 是系动词，his bicycle 是表语；his 在 bicycle 前用作物主限定词。 Whose scarf 是疑问词组，询问归属；is 前置，that 是主语。whose 后接 scarf，不能换成 who&#39;s。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-012">回看本课</a></p><h2 id="lesson-13-·-形容词位置与颜色问句" tabindex="-1">Lesson 13 · 形容词位置与颜色问句 <a class="header-anchor" href="#lesson-13-·-形容词位置与颜色问句" aria-label="Permalink to &quot;Lesson 13 · 形容词位置与颜色问句 {#lesson-13-·-形容词位置与颜色问句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Her new jacket is green.</p><h3 id="练习-1-12" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-12" aria-label="Permalink to &quot;练习 1 {#练习-1-12}&quot;">​</a></h3><p>填 be：What colour ___ your shoes?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> are</p><p><strong>解析：</strong> 按本课规则判断：颜色、大小等形容词可放在名词前，也可放在 be 后。单数名词前的冠词放在形容词前，如 a blue jacket。询问颜色用 What colour is/are ...?，be 与所问物品的单复数一致。多个形容词的排序初学阶段先掌握“新旧 + 颜色 + 名词”，如 a new blue jacket。</p></details><p><strong>表达迁移：</strong> 围绕“描述服装的颜色与新旧”写两至三句，再读给同伴听。至少使用一次形容词位置与颜色问句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Her new jacket is green. What colour are your shoes?</p><p>Her new jacket 是主语，new 修饰 jacket；green 位于 is 后作表语，表示颜色，不需要冠词。 What colour 询问颜色，are 与复数主语 your shoes 一致；不因 colour 是单数而改用 is。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-013">回看本课</a></p><h2 id="lesson-14-·-形容词位置与颜色问句" tabindex="-1">Lesson 14 · 形容词位置与颜色问句 <a class="header-anchor" href="#lesson-14-·-形容词位置与颜色问句" aria-label="Permalink to &quot;Lesson 14 · 形容词位置与颜色问句 {#lesson-14-·-形容词位置与颜色问句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> What colour are your shoes?</p><h3 id="练习-1-13" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-13" aria-label="Permalink to &quot;练习 1 {#练习-1-13}&quot;">​</a></h3><p>将“蓝色的新外套”写成名词短语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> a new blue coat</p><p><strong>解析：</strong> 按本课规则判断：颜色、大小等形容词可放在名词前，也可放在 be 后。单数名词前的冠词放在形容词前，如 a blue jacket。询问颜色用 What colour is/are ...?，be 与所问物品的单复数一致。多个形容词的排序初学阶段先掌握“新旧 + 颜色 + 名词”，如 a new blue jacket。</p></details><p><strong>表达迁移：</strong> 围绕“描述服装的颜色与新旧”写两至三句，再读给同伴听。至少使用一次形容词位置与颜色问句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>What colour are your shoes? Her new jacket is green.</p><p>What colour 询问颜色，are 与复数主语 your shoes 一致；不因 colour 是单数而改用 is。 Her new jacket 是主语，new 修饰 jacket；green 位于 is 后作表语，表示颜色，不需要冠词。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-014">回看本课</a></p><h2 id="lesson-15-·-名词复数与复数-be" tabindex="-1">Lesson 15 · 名词复数与复数 be <a class="header-anchor" href="#lesson-15-·-名词复数与复数-be" aria-label="Permalink to &quot;Lesson 15 · 名词复数与复数 be {#lesson-15-·-名词复数与复数-be}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> These tourists are from Spain.</p><h3 id="练习-1-14" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-14" aria-label="Permalink to &quot;练习 1 {#练习-1-14}&quot;">​</a></h3><p>填 be：These tourists ___ from Spain.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> are</p><p><strong>解析：</strong> 按本课规则判断：多数可数名词复数加 s；以 s、sh、ch 等结尾常加 es。you 既可指一人也可指多人，be 都用 are。we 和 they 也用 are。these/those 指复数对象，不能与 is 或单数 passport 搭配。称呼多人时，your 本身不加 s；数量信息由后面的名词体现。</p></details><p><strong>表达迁移：</strong> 围绕“多人场景下核对身份和证件”写两至三句，再读给同伴听。至少使用一次名词复数与复数 be，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>These tourists are from Spain. Are these your passports?</p><p>These tourists 是复数主语，are from Spain 表来源；these 与复数 tourists 配合，Spain 是国家专名。 Are 前置，these 是复数主语，your passports 是复数名词表语；your 的形式不因多人多本护照而改变。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-015">回看本课</a></p>',68)])])}const g=s(t,[["render",n]]);export{d as __pageData,g as default};
